// Minimal proto3 codec driven by schema.json (generated by gen_proto.py from
// RustDesk's .proto files). Messages are plain objects keyed by field name;
// 64-bit integers decode to numbers when they fit, otherwise to bigint;
// enums are numbers; bytes are Uint8Array.

import schemaJson from "./schema.json";

type Field = [number, string, string, number, string]; // no, name, kind, repeated, oneof
const schema = schemaJson as unknown as { messages: Record<string, Field[]>; enums: Record<string, Record<string, number>> };

export type Msg = Record<string, any>;

export const enums = schema.enums;

const byNo = new Map<string, Map<number, Field>>();
function fieldsByNo(type: string): Map<number, Field> {
  let m = byNo.get(type);
  if (!m) {
    const fields = schema.messages[type];
    if (!fields) throw new Error("unknown message type " + type);
    m = new Map(fields.map((f) => [f[0], f]));
    byNo.set(type, m);
  }
  return m;
}

// ---------------------------------------------------------------- writer

class Writer {
  buf: Uint8Array<ArrayBuffer> = new Uint8Array(256);
  len = 0;
  private grow(n: number) {
    if (this.len + n <= this.buf.length) return;
    let size = this.buf.length * 2;
    while (size < this.len + n) size *= 2;
    const b = new Uint8Array(size);
    b.set(this.buf.subarray(0, this.len));
    this.buf = b;
  }
  byte(b: number) {
    this.grow(1);
    this.buf[this.len++] = b;
  }
  bytes(b: Uint8Array) {
    this.grow(b.length);
    this.buf.set(b, this.len);
    this.len += b.length;
  }
  varint(v: number | bigint) {
    let n = BigInt.asUintN(64, BigInt(v));
    while (n >= 0x80n) {
      this.byte(Number(n & 0x7fn) | 0x80);
      n >>= 7n;
    }
    this.byte(Number(n));
  }
  tag(no: number, wire: number) {
    this.varint((no << 3) | wire);
  }
  fixed32(v: number, float: boolean) {
    const d = new DataView(new ArrayBuffer(4));
    if (float) d.setFloat32(0, v, true);
    else d.setUint32(0, v >>> 0, true);
    this.bytes(new Uint8Array(d.buffer));
  }
  fixed64(v: number | bigint, float: boolean) {
    const d = new DataView(new ArrayBuffer(8));
    if (float) d.setFloat64(0, Number(v), true);
    else d.setBigUint64(0, BigInt.asUintN(64, BigInt(v)), true);
    this.bytes(new Uint8Array(d.buffer));
  }
  finish() {
    return this.buf.slice(0, this.len);
  }
}

const te = new TextEncoder();
const td = new TextDecoder();

function isDefault(kind: string, v: any): boolean {
  if (v === undefined || v === null) return true;
  if (kind.startsWith("message:")) return false;
  if (kind === "string") return v === "";
  if (kind === "bytes") return v.length === 0;
  if (kind === "bool") return v === false;
  return v === 0 || v === 0n;
}

function writeValue(w: Writer, no: number, kind: string, v: any) {
  switch (kind) {
    case "int32":
    case "int64":
    case "uint32":
    case "uint64":
    case "enum":
      w.tag(no, 0);
      w.varint(v);
      return;
    case "bool":
      w.tag(no, 0);
      w.varint(v ? 1 : 0);
      return;
    case "sint32":
    case "sint64": {
      const n = BigInt(v);
      w.tag(no, 0);
      w.varint((n << 1n) ^ (n < 0n ? -1n : 0n));
      return;
    }
    case "fixed32":
    case "sfixed32":
    case "float":
      w.tag(no, 5);
      w.fixed32(v, kind === "float");
      return;
    case "fixed64":
    case "sfixed64":
    case "double":
      w.tag(no, 1);
      w.fixed64(v, kind === "double");
      return;
    case "string": {
      const b = te.encode(v);
      w.tag(no, 2);
      w.varint(b.length);
      w.bytes(b);
      return;
    }
    case "bytes":
      w.tag(no, 2);
      w.varint(v.length);
      w.bytes(v);
      return;
    default: {
      const b = encode(kind.slice(8), v);
      w.tag(no, 2);
      w.varint(b.length);
      w.bytes(b);
    }
  }
}

export function encode(type: string, obj: Msg): Uint8Array<ArrayBuffer> {
  const w = new Writer();
  for (const [no, name, kind, repeated] of schema.messages[type]) {
    const v = obj[name];
    if (repeated) {
      if (Array.isArray(v)) for (const x of v) writeValue(w, no, kind, x);
    } else if (!isDefault(kind, v) || (v !== undefined && v !== null && kind.startsWith("message:"))) {
      writeValue(w, no, kind, v);
    }
  }
  return w.finish();
}

// ---------------------------------------------------------------- reader

class Reader {
  pos = 0;
  constructor(public buf: Uint8Array) {}
  varint(): bigint {
    let shift = 0n;
    let out = 0n;
    for (;;) {
      if (this.pos >= this.buf.length) throw new Error("truncated varint");
      const b = this.buf[this.pos++];
      out |= BigInt(b & 0x7f) << shift;
      if (b < 0x80) return out;
      shift += 7n;
      if (shift > 70n) throw new Error("varint too long");
    }
  }
  bytes(n: number) {
    if (this.pos + n > this.buf.length) throw new Error("truncated field");
    const b = this.buf.subarray(this.pos, this.pos + n);
    this.pos += n;
    return b;
  }
}

function num(v: bigint): number | bigint {
  return v >= BigInt(Number.MIN_SAFE_INTEGER) && v <= BigInt(Number.MAX_SAFE_INTEGER) ? Number(v) : v;
}

function readScalar(r: Reader, kind: string, wire: number): any {
  switch (kind) {
    case "int32":
      return Number(BigInt.asIntN(32, r.varint()));
    case "enum":
      return Number(BigInt.asIntN(32, r.varint()));
    case "uint32":
      return Number(BigInt.asUintN(32, r.varint()));
    case "int64":
      return num(BigInt.asIntN(64, r.varint()));
    case "uint64":
      return num(BigInt.asUintN(64, r.varint()));
    case "bool":
      return r.varint() !== 0n;
    case "sint32":
    case "sint64": {
      const n = r.varint();
      return num((n >> 1n) ^ -(n & 1n));
    }
    case "fixed32":
    case "sfixed32":
    case "float": {
      const b = r.bytes(4);
      const d = new DataView(b.buffer, b.byteOffset, 4);
      return kind === "float" ? d.getFloat32(0, true) : kind === "sfixed32" ? d.getInt32(0, true) : d.getUint32(0, true);
    }
    case "fixed64":
    case "sfixed64":
    case "double": {
      const b = r.bytes(8);
      const d = new DataView(b.buffer, b.byteOffset, 8);
      return kind === "double" ? d.getFloat64(0, true) : num(kind === "sfixed64" ? d.getBigInt64(0, true) : d.getBigUint64(0, true));
    }
  }
  throw new Error("bad scalar " + kind + " wire " + wire);
}

function skip(r: Reader, wire: number) {
  if (wire === 0) r.varint();
  else if (wire === 1) r.bytes(8);
  else if (wire === 2) r.bytes(Number(r.varint()));
  else if (wire === 5) r.bytes(4);
  else throw new Error("unsupported wire type " + wire);
}

const packable = (kind: string) => kind !== "string" && kind !== "bytes" && !kind.startsWith("message:");

export function decode(type: string, buf: Uint8Array): Msg {
  const fields = fieldsByNo(type);
  const r = new Reader(buf);
  const out: Msg = {};
  while (r.pos < buf.length) {
    const tag = Number(r.varint());
    const no = tag >>> 3;
    const wire = tag & 7;
    const f = fields.get(no);
    if (!f) {
      skip(r, wire);
      continue;
    }
    const [, name, kind, repeated] = f;
    if (repeated && wire === 2 && packable(kind)) {
      const sub = new Reader(r.bytes(Number(r.varint())));
      const arr = (out[name] ||= []);
      const w = kind === "double" || kind === "fixed64" || kind === "sfixed64" ? 1 : kind === "float" || kind === "fixed32" || kind === "sfixed32" ? 5 : 0;
      while (sub.pos < sub.buf.length) arr.push(readScalar(sub, kind, w));
      continue;
    }
    let v: any;
    if (kind === "string") v = td.decode(r.bytes(Number(r.varint())));
    else if (kind === "bytes") v = r.bytes(Number(r.varint())).slice();
    else if (kind.startsWith("message:")) v = decode(kind.slice(8), r.bytes(Number(r.varint())));
    else v = readScalar(r, kind, wire);
    if (repeated) (out[name] ||= []).push(v);
    else out[name] = v;
  }
  return out;
}
